    #include <iostream>

class BeverageMaker {
public:
    virtual void brew() = 0;
    virtual void addCondiments() = 0;
};

class TeaMaker : public BeverageMaker {
public:
    // Implementing abstract methods
    void brew() override {
        std::cout << "Steeping the tea" << std::endl;
    }

    void addCondiments() override {
        std::cout << "Adding lemon" << std::endl;
    }
};


