            C++

    #include <iostream>
using namespace std;

// Abstract class defining the template method
class BeverageMaker {
public:
    // Template method defining the overall process
    void makeBeverage() {
        boilWater();
        brew();
        pourInCup();
        addCondiments();
    }

    // Abstract methods to be implemented by subclasses
    virtual void brew() = 0;
    virtual void addCondiments() = 0;

    // Common methods
    void boilWater() {
        cout << "Boiling water" << endl;
    }

    void pourInCup() {
        cout << "Pouring into cup" << endl;
    }
};

// Concrete subclass for making tea
class TeaMaker : public BeverageMaker {
public:
    // Implementing abstract methods
    void brew() override {
        cout << "Steeping the tea" << endl;
    }

    void addCondiments() override {
        cout << "Adding lemon" << endl;
    }
};

// Concrete subclass for making coffee
class CoffeeMaker : public BeverageMaker {
public:
    // Implementing abstract methods
    void brew() override {
        cout << "Dripping coffee through filter" << endl;
    }

    void addCondiments() override {
        cout << "Adding sugar and milk" << endl;
    }
};

int main() {
    cout << "Making tea:" << endl;
    TeaMaker teaMaker;
    teaMaker.makeBeverage();

    cout << "\nMaking coffee:" << endl;
    CoffeeMaker coffeeMaker;
    coffeeMaker.makeBeverage();

    return 0;
}


